import { Button } from "@/registry/erbium/ui/button";
import { ButtonGroup } from "@/registry/erbium/ui/button-group";
import { Kbd } from "@/registry/erbium/ui/kbd";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/registry/erbium/ui/tooltip";

export default function KbdTooltip() {
  return (
    <div className="flex flex-wrap gap-group">
      <ButtonGroup>
        <Tooltip>
          <TooltipTrigger
            render={
              <Button size="sm" variant="outline">
                Save
              </Button>
            }
          />
          <TooltipContent>
            Save Changes <Kbd hotkey="S" />
          </TooltipContent>
        </Tooltip>
        <Tooltip>
          <TooltipTrigger
            render={
              <Button size="sm" variant="outline">
                Print
              </Button>
            }
          />
          <TooltipContent>
            Print Document <Kbd hotkey="Mod+P" />
          </TooltipContent>
        </Tooltip>
      </ButtonGroup>
    </div>
  );
}

import ExampleKbdTooltip from "../examples/kbd-tooltip";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleKbdTooltip />
  </div>
);

export default Example;
